
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_cap0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_cap0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.284355249087104e+00, -3.221651907283269e+00, -3.133813161521289e+00, -3.012187043963731e+00, -2.846574107805321e+00, -2.626430381730540e+00, -2.343745259015941e+00, -1.998351983815553e+00, -1.605554871965874e+00, -1.201389124570954e+00, -8.224236900487647e-01, -5.699944476233888e-01, -4.986698263019643e-01, -4.080587109477395e-01, -2.925256310958309e-01, -1.883321054217592e-01, -1.283282021130968e-01, -1.162103451473681e-01, -1.417278697531149e-01, -1.914708304615801e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


